// C documentation
//
//	/* for APC houses */
//	/* n  number of house
//	 * ph geographic latitude
//	 * e  ecliptic obliquity
//	 * az armc
//	 */
func apc_sector(tls *libc.TLS, n int32, ph float64, e float64, az float64) (r float64) {
	var a, dasc, dret, kv float64
	var is_below_hor, k int32
	_, _, _, _, _, _ = a, dasc, dret, is_below_hor, k, kv
	is_below_hor = 0
	/* kv: ascensional difference of the ascendant */
	/* dasc: declination of the ascendant */
	if libc.Xfabs(tls, float64(ph*(libc.Float64FromFloat64(180)/libc.Float64FromFloat64(3.141592653589793)))) > libc.Float64FromInt32(90)-libc.Float64FromFloat64(1e-10) {
		kv = libc.Float64FromInt32(0)
		dasc = libc.Float64FromInt32(0)
	} else {
		kv = libc.Xatan(tls, float64(float64(libc.Xtan(tls, ph)*libc.Xtan(tls, e))*libc.Xcos(tls, az))/(libc.Float64FromInt32(1)+float64(float64(libc.Xtan(tls, ph)*libc.Xtan(tls, e))*libc.Xsin(tls, az))))
		if libc.Xfabs(tls, float64(ph*(libc.Float64FromFloat64(180)/libc.Float64FromFloat64(3.141592653589793)))) < float64(1e-10) {
			dasc = float64((libc.Float64FromInt32(90) - libc.Float64FromFloat64(1e-10)) * (libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180)))
			if ph < libc.Float64FromInt32(0) {
				dasc = -dasc
			}
		} else {
			dasc = libc.Xatan(tls, libc.Xsin(tls, kv)/libc.Xtan(tls, ph))
		}
	}
	/* note, at polar circles, when the mc sinks below the horizon,
	 * kv and dasc change sign in the above formulae.
	 * this is what we need, because the ascendand jumps by 180 deg */
	/* printf("%f, %f\n", kv*RADTODEG, dasc*RADTODEG); */
	if n < int32(8) {
		is_below_hor = int32(1) /* 1 and 7 are included here */
		k = n - int32(1)
	} else {
		k = n - int32(13)
	}
	/* az + PI/2 + kv = armc + 90 + asc. diff. = right ascension of ascendant
	 * PI/2 +- kv = semi-diurnal or seminocturnal arc of ascendant
	 * a = right ascension of house cusp on apc circle (ascendant-parallel
	 * circle), with declination dasc */
	if is_below_hor != 0 {
		a = kv + az + libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromInt32(2) + float64(float64(k)*(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromInt32(2)-kv))/libc.Float64FromInt32(3)
	} else {
		a = kv + az + libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromInt32(2) + float64(float64(k)*(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromInt32(2)+kv))/libc.Float64FromInt32(3)
	}
	a = Xswe_radnorm(tls, a)
	dret = libc.Xatan2(tls, float64(float64(libc.Xtan(tls, dasc)*libc.Xtan(tls, ph))*libc.Xsin(tls, az))+libc.Xsin(tls, a), float64(libc.Xcos(tls, e)*(float64(float64(libc.Xtan(tls, dasc)*libc.Xtan(tls, ph))*libc.Xcos(tls, az))+libc.Xcos(tls, a)))+float64(float64(libc.Xsin(tls, e)*libc.Xtan(tls, ph))*libc.Xsin(tls, az-a)))
	dret = Xswe_degnorm(tls, float64(dret*(libc.Float64FromFloat64(180)/libc.Float64FromFloat64(3.141592653589793))))
	return dret
}

