// How to deal with Sunshine houses if the southern crossing point of Equator
// and Ecliptic is under the horizon:
// We follow the proposal by Dieter Koch, who wants to keep it in analogy with
// Regiomontanus, where we keep the MC above the horizon, by switching it to the north.
// This results in an clockwise sequence of house cusps in the chart.
//
// One can argue that the MC should be kept south, even when it is under the horizon.
// This would keep the sequence of houses in the chart counterclockwise as usual.
// To achieve it, the offsets on the diurnal arcs must be inverted.

func Xswi_armc_to_mc(tls *libc.TLS, armc float64, eps float64) (r float64) {
	var mc, tant float64
	_, _ = mc, tant
	if libc.Xfabs(tls, armc-libc.Float64FromInt32(90)) > float64(1e-10) && libc.Xfabs(tls, armc-libc.Float64FromInt32(270)) > float64(1e-10) {
		tant = libc.Xtan(tls, float64(armc*(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromFloat64(180))))
		mc = float64(libc.Xatan(tls, tant/libc.Xcos(tls, float64(eps*(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromFloat64(180))))) * (libc.Float64FromFloat64(180) / libc.Float64FromFloat64(3.141592653589793)))
		if armc > libc.Float64FromInt32(90) && armc <= libc.Float64FromInt32(270) {
			mc = Xswe_degnorm(tls, mc+libc.Float64FromInt32(180))
		}
	} else {
		if libc.Xfabs(tls, armc-libc.Float64FromInt32(90)) <= float64(1e-10) {
			mc = libc.Float64FromInt32(90)
		} else {
			mc = libc.Float64FromInt32(270)
		}
	} /*  if */
	return mc
}

