				*(*float64)(unsafe.Pointer(pdp + 224 + 3*8)) -= float64((*(*[2]float64)(unsafe.Pointer(bp)))[int32(1)] * (libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180)))
