// C documentation
//
//	/* Reduce x modulo 360 degrees
//	 */
func Xswe_degnorm(tls *libc.TLS, x float64) (r float64) {
	var y float64
	_ = y
	y = libc.Xfmod(tls, x, float64(360))
	if libc.Xfabs(tls, y) < float64(1e-13) {
		y = libc.Float64FromInt32(0)
	} /* Alois fix 11-dec-1999 */
	if y < float64(0) {
		y += float64(360)
	}
	return y
}

