func Xswi_ldp_peps(tls *libc.TLS, tjd float64, dpre uintptr, deps uintptr) {
	var a, c, p, q, s, t, w float64
	var i, nper, npol int32
	_, _, _, _, _, _, _, _, _, _ = a, c, i, nper, npol, p, q, s, t, w
	npol = int32(NPOL_PEPS)
	nper = int32(NPER_PEPS)
	t = (tjd - float64(2.451545e+06)) / float64(36525)
	p = libc.Float64FromInt32(0)
	q = libc.Float64FromInt32(0)
	/* periodic terms */
	i = 0
	for {
		if !(i < nper) {
			break
		}
		w = float64(float64(libc.Float64FromFloat64(2)*libc.Float64FromFloat64(3.141592653589793)) * t)
		a = w / *(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&peper)) + uintptr(i)*8))
		s = libc.Xsin(tls, a)
		c = libc.Xcos(tls, a)
		p += float64(c**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&peper)) + 1*80 + uintptr(i)*8))) + float64(s**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&peper)) + 3*80 + uintptr(i)*8)))
		q += float64(c**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&peper)) + 2*80 + uintptr(i)*8))) + float64(s**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&peper)) + 4*80 + uintptr(i)*8)))
		goto _1
	_1:
		;
		i++
	}
	/* polynomial terms */
	w = libc.Float64FromInt32(1)
	i = 0
	for {
		if !(i < npol) {
			break
		}
		p += float64(*(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pepol)) + uintptr(i)*16)) * w)
		q += float64(*(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pepol)) + uintptr(i)*16 + 1*8)) * w)
		w *= t
		goto _2
	_2:
		;
		i++
	}
	/* both to radians */
	p *= libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180) / float64(3600)
	q *= libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180) / float64(3600)
	/* return */
	if dpre != libc.UintptrFromInt32(0) {
		*(*float64)(unsafe.Pointer(dpre)) = p
	}
	if deps != libc.UintptrFromInt32(0) {
		*(*float64)(unsafe.Pointer(deps)) = q
	}
	// fprintf(stderr, "%.17f\n", *deps / DEGTORAD);
}

// C documentation
//
//	/*
//	 * Long term high precision precession,
//	 * according to Vondrak/Capitaine/Wallace, "New precession expressions, valid
//	 * for long time intervals", in A&A 534, A22(2011).
//	 */
//	/* precession of the ecliptic */
func pre_pecl(tls *libc.TLS, tjd float64, vec uintptr) {
	var a, c, p, q, s, t, w, z float64
	var i, nper, npol int32
	_, _, _, _, _, _, _, _, _, _, _ = a, c, i, nper, npol, p, q, s, t, w, z
	npol = int32(NPOL_PECL)
	nper = int32(NPER_PECL)
	t = (tjd - float64(2.451545e+06)) / float64(36525)
	p = libc.Float64FromInt32(0)
	q = libc.Float64FromInt32(0)
	/* periodic terms */
	i = 0
	for {
		if !(i < nper) {
			break
		}
		w = float64(float64(libc.Float64FromFloat64(2)*libc.Float64FromFloat64(3.141592653589793)) * t)
		a = w / *(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pqper)) + uintptr(i)*8))
		s = libc.Xsin(tls, a)
		c = libc.Xcos(tls, a)
		p += float64(c**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pqper)) + 1*64 + uintptr(i)*8))) + float64(s**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pqper)) + 3*64 + uintptr(i)*8)))
		q += float64(c**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pqper)) + 2*64 + uintptr(i)*8))) + float64(s**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pqper)) + 4*64 + uintptr(i)*8)))
		goto _1
	_1:
		;
		i++
	}
	/* polynomial terms */
	w = libc.Float64FromInt32(1)
	i = 0
	for {
		if !(i < npol) {
			break
		}
		p += float64(*(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pqpol)) + uintptr(i)*16)) * w)
		q += float64(*(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&pqpol)) + uintptr(i)*16 + 1*8)) * w)
		w *= t
		goto _2
	_2:
		;
		i++
	}
	/* both to radians */
	p *= libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180) / float64(3600)
	q *= libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180) / float64(3600)
	/* ecliptic pole vector */
	z = libc.Float64FromInt32(1) - float64(p*p) - float64(q*q)
	if z < libc.Float64FromInt32(0) {
		z = libc.Float64FromInt32(0)
	} else {
		z = libc.Xsqrt(tls, z)
	}
	s = libc.Xsin(tls, float64(float64(84381.406)*(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromFloat64(180)/float64(3600))))
	c = libc.Xcos(tls, float64(float64(84381.406)*(libc.Float64FromFloat64(3.141592653589793)/libc.Float64FromFloat64(180)/float64(3600))))
	*(*float64)(unsafe.Pointer(vec)) = p
	*(*float64)(unsafe.Pointer(vec + 1*8)) = float64(-q*c) - float64(z*s)
	*(*float64)(unsafe.Pointer(vec + 2*8)) = float64(-q*s) + float64(z*c)
}

// C documentation
//
//	/* precession of the equator */
func pre_pequ(tls *libc.TLS, tjd float64, veq uintptr) {
	var a, c, s, t, w, x, y float64
	var i, nper, npol int32
	_, _, _, _, _, _, _, _, _, _ = a, c, i, nper, npol, s, t, w, x, y
	npol = int32(NPOL_PEQU)
	nper = int32(NPER_PEQU)
	t = (tjd - float64(2.451545e+06)) / float64(36525)
	x = libc.Float64FromInt32(0)
	y = libc.Float64FromInt32(0)
	i = 0
	for {
		if !(i < nper) {
			break
		}
		w = float64(float64(libc.Float64FromFloat64(2)*libc.Float64FromFloat64(3.141592653589793)) * t)
		a = w / *(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&xyper)) + uintptr(i)*8))
		s = libc.Xsin(tls, a)
		c = libc.Xcos(tls, a)
		x += float64(c**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&xyper)) + 1*112 + uintptr(i)*8))) + float64(s**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&xyper)) + 3*112 + uintptr(i)*8)))
		y += float64(c**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&xyper)) + 2*112 + uintptr(i)*8))) + float64(s**(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&xyper)) + 4*112 + uintptr(i)*8)))
		goto _1
	_1:
		;
		i++
	}
	/* polynomial terms */
	w = libc.Float64FromInt32(1)
	i = 0
	for {
		if !(i < npol) {
			break
		}
		x += float64(*(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&xypol)) + uintptr(i)*16)) * w)
		y += float64(*(*float64)(unsafe.Pointer(uintptr(unsafe.Pointer(&xypol)) + uintptr(i)*16 + 1*8)) * w)
		w *= t
		goto _2
	_2:
		;
		i++
	}
	x *= libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180) / float64(3600)
	y *= libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180) / float64(3600)
	/* equator pole vector */
	*(*float64)(unsafe.Pointer(veq)) = x
	*(*float64)(unsafe.Pointer(veq + 1*8)) = y
	w = float64(x*x) + float64(y*y)
	if w < libc.Float64FromInt32(1) {
		*(*float64)(unsafe.Pointer(veq + 2*8)) = libc.Xsqrt(tls, libc.Float64FromInt32(1)-w)
	} else {
		*(*float64)(unsafe.Pointer(veq + 2*8)) = libc.Float64FromInt32(0)
	}
}

// C documentation
//
//	/* precession matrix */
func pre_pmat(tls *libc.TLS, tjd float64, rp uintptr) {
	bp := tls.Alloc(96)
	defer tls.Free(96)
	var w float64
	var _ /* eqx at bp+72 */ [3]float64
	var _ /* pecl at bp+24 */ [3]float64
	var _ /* peqr at bp+0 */ [3]float64
	var _ /* v at bp+48 */ [3]float64
	_ = w
	//tjd = 1219339.078000;
	/*equator pole */
	pre_pequ(tls, tjd, bp)
	/* ecliptic pole */
	pre_pecl(tls, tjd, bp+24)
	//  fprintf(stderr, "%.17f %.17f %.17f\n", peqr[0], peqr[1], peqr[2]);
	//  fprintf(stderr, "%.17f %.17f %.17f\n", pecl[0], pecl[1], pecl[2]);
	/* equinox */
	Xswi_cross_prod(tls, bp, bp+24, bp+48)
	w = libc.Xsqrt(tls, float64((*(*[3]float64)(unsafe.Pointer(bp + 48)))[0]*(*(*[3]float64)(unsafe.Pointer(bp + 48)))[0])+float64((*(*[3]float64)(unsafe.Pointer(bp + 48)))[int32(1)]*(*(*[3]float64)(unsafe.Pointer(bp + 48)))[int32(1)])+float64((*(*[3]float64)(unsafe.Pointer(bp + 48)))[int32(2)]*(*(*[3]float64)(unsafe.Pointer(bp + 48)))[int32(2)]))
	(*(*[3]float64)(unsafe.Pointer(bp + 72)))[0] = (*(*[3]float64)(unsafe.Pointer(bp + 48)))[0] / w
	(*(*[3]float64)(unsafe.Pointer(bp + 72)))[int32(1)] = (*(*[3]float64)(unsafe.Pointer(bp + 48)))[int32(1)] / w
	(*(*[3]float64)(unsafe.Pointer(bp + 72)))[int32(2)] = (*(*[3]float64)(unsafe.Pointer(bp + 48)))[int32(2)] / w
	Xswi_cross_prod(tls, bp, bp+72, bp+48)
	*(*float64)(unsafe.Pointer(rp)) = (*(*[3]float64)(unsafe.Pointer(bp + 72)))[0]
	*(*float64)(unsafe.Pointer(rp + 1*8)) = (*(*[3]float64)(unsafe.Pointer(bp + 72)))[int32(1)]
	*(*float64)(unsafe.Pointer(rp + 2*8)) = (*(*[3]float64)(unsafe.Pointer(bp + 72)))[int32(2)]
	*(*float64)(unsafe.Pointer(rp + 3*8)) = (*(*[3]float64)(unsafe.Pointer(bp + 48)))[0]
	*(*float64)(unsafe.Pointer(rp + 4*8)) = (*(*[3]float64)(unsafe.Pointer(bp + 48)))[int32(1)]
	*(*float64)(unsafe.Pointer(rp + 5*8)) = (*(*[3]float64)(unsafe.Pointer(bp + 48)))[int32(2)]
	*(*float64)(unsafe.Pointer(rp + 6*8)) = (*(*[3]float64)(unsafe.Pointer(bp)))[0]
	*(*float64)(unsafe.Pointer(rp + 7*8)) = (*(*[3]float64)(unsafe.Pointer(bp)))[int32(1)]
	*(*float64)(unsafe.Pointer(rp + 8*8)) = (*(*[3]float64)(unsafe.Pointer(bp)))[int32(2)]
	// int i;
	//
	//	for (i = 0; i < 3; i++) {
	//	  fprintf(stderr, "(%.17f   %.17f   %.17f)\n", rp[i*3], rp[i*3+1],rp[i*3+2]);
	//	} /**/
}

// C documentation
//
//	/* precession according to Owen 1990:
//	 * Owen, William M., Jr., (JPL) "A Theory of the Earth's Precession
//	 * Relative to the Invariable Plane of the Solar System", Ph.D.
//	 * Dissertation, University of Florida, 1990.
//	 * Implemented for time range -18000 to 14000.
