	if t >= float64(n-int32(1)) {
		ans = *(*float64)(unsafe.Pointer(v + uintptr(n-int32(1))*8))
		goto done
	}
	p = libc.Xfloor(tls, t)
	iy = int32(t)
	/* Zeroth order estimate is value at start of year */
