	k = iy + int32(1)
	if k >= n {
		goto done
	}
	/* The fraction of tabulation interval */
	p = t - p
	ans += float64(p * (*(*float64)(unsafe.Pointer(v + uintptr(k)*8)) - *(*float64)(unsafe.Pointer(v + uintptr(iy)*8))))
	if iy-int32(1) < 0 || iy+int32(2) >= n {
		goto done
	} /* can't do second differences */
	/* Make table of first differences */
	k = iy - int32(2)
	i = 0
	for {
		if !(i < int32(5)) {
			break
		}
		if k < 0 || k+int32(1) >= n {
			d[i] = libc.Float64FromInt32(0)
		} else {
			d[i] = *(*float64)(unsafe.Pointer(v + uintptr(k+int32(1))*8)) - *(*float64)(unsafe.Pointer(v + uintptr(k)*8))
		}
		k += int32(1)
		goto _1
	_1:
		;
		i++
	}
	/* Compute second differences */
	i = 0
	for {
		if !(i < int32(4)) {
			break
		}
		d[i] = d[i+int32(1)] - d[i]
		goto _2
	_2:
		;
		i++
	}
	B = float64(float64(float64(0.25)*p) * (p - float64(1)))
	ans += float64(B * (d[int32(1)] + d[int32(2)]))
	if iy+int32(2) >= n {
		goto done
	}
	/* Compute third differences */
	i = 0
	for {
		if !(i < int32(3)) {
			break
		}
		d[i] = d[i+int32(1)] - d[i]
		goto _3
	_3:
		;
		i++
	}
