	i = 0
	for {
		if !(i < int32(2)) {
			break
		}
		d[i] = d[i+int32(1)] - d[i]
		goto _4
	_4:
		;
		i++
	}
	B = float64(float64(float64(float64(0.125)*B)*(p+float64(1))) * (p - float64(2)))
	ans += float64(B * (d[0] + d[int32(1)]))
	goto done
