// C documentation
//
//	/*************************************
//	round second, but at 29.5959 always down
//	*************************************/
func Xswe_csroundsec(tls *libc.TLS, x centisec) (r centisec) {
	var t centisec
	_ = t
	t = int32(int64((x+int32(50))/int32(100)) * int64(100))                 /* round to seconds */
	if t > x && t%(libc.Int32FromInt32(30)*libc.Int32FromInt32(DEG)) == 0 { /* was rounded up to next sign */
		t = int32(int64(x/int32(100)) * int64(100))
	} /* round last second of sign downwards */
	return t
}

// C documentation
