// C documentation
//
//	/******************************************************************
//	 * decimal degrees in zodiac to nakshatra position, deg, min, sec *
//	 * for definition of input see function swe_split_deg().
//	 * output:
//	 * ideg 	degrees,
//	 * imin 	minutes,
//	 * isec 	seconds,
//	 * dsecfr	fraction of seconds
//	 * inak	nakshatra number;
//	 ******************************************************************/
func split_deg_nakshatra(tls *libc.TLS, ddeg float64, roundflag int321, ideg uintptr, imin uintptr, isec uintptr, dsecfr uintptr, inak uintptr) {
	var dadd, ddeghelp, dnakshsize float64
	_, _, _ = dadd, ddeghelp, dnakshsize
	dadd = libc.Float64FromInt32(0)
	dnakshsize = float64(13.33333333333333)
	ddeghelp = libc.Xfmod(tls, ddeg, dnakshsize)
	*(*int321)(unsafe.Pointer(inak)) = int32(1)
	if ddeg < libc.Float64FromInt32(0) {
		*(*int321)(unsafe.Pointer(inak)) = -int32(1)
		ddeg = libc.Float64FromInt32(0)
	}
	// Sheoran "Vedic" ayanamsha: 0 Aries = 3°20 Ashvini
	if Xswed.Fsidd.Fsid_mode&int32(SE_SIDM_TRUE_SHEORAN) == int32(SE_SIDM_TRUE_SHEORAN) {
		ddeg = Xswe_degnorm(tls, ddeg+float64(3.33333333333333))
	}
	if roundflag&int32(SE_SPLIT_DEG_ROUND_DEG) != 0 {
		dadd = float64(0.5)
	} else {
		if roundflag&int32(SE_SPLIT_DEG_ROUND_MIN) != 0 {
			dadd = libc.Float64FromFloat64(0.5) / libc.Float64FromInt32(60)
		} else {
			if roundflag&int32(SE_SPLIT_DEG_ROUND_SEC) != 0 {
				dadd = libc.Float64FromFloat64(0.5) / libc.Float64FromInt32(3600)
			}
		}
	}
	if roundflag&int32(SE_SPLIT_DEG_KEEP_DEG) != 0 {
		if int32(ddeghelp+dadd)-int32(ddeghelp) > 0 {
			dadd = libc.Float64FromInt32(0)
		}
	} else {
		if roundflag&int32(SE_SPLIT_DEG_KEEP_SIGN) != 0 {
			if ddeghelp+dadd >= dnakshsize {
				dadd = libc.Float64FromInt32(0)
			}
		}
	}
	ddeg += dadd
	*(*int321)(unsafe.Pointer(inak)) = int32(ddeg / dnakshsize)
	if *(*int321)(unsafe.Pointer(inak)) == int32(27) {
		*(*int321)(unsafe.Pointer(inak)) = 0
	} // with rounding up from 359.9999
	ddeg = libc.Xfmod(tls, ddeg, dnakshsize)
	*(*int321)(unsafe.Pointer(ideg)) = int32(ddeg)
	ddeg -= float64(*(*int321)(unsafe.Pointer(ideg)))
	*(*int321)(unsafe.Pointer(imin)) = int32(float64(ddeg * libc.Float64FromInt32(60)))
	ddeg -= float64(*(*int321)(unsafe.Pointer(imin))) / float64(60)
	*(*int321)(unsafe.Pointer(isec)) = int32(float64(ddeg * libc.Float64FromInt32(3600)))
	if !(roundflag&(libc.Int32FromInt32(SE_SPLIT_DEG_ROUND_DEG)|libc.Int32FromInt32(SE_SPLIT_DEG_ROUND_MIN)|libc.Int32FromInt32(SE_SPLIT_DEG_ROUND_SEC)) != 0) {
		*(*float64)(unsafe.Pointer(dsecfr)) = float64(ddeg*libc.Float64FromInt32(3600)) - float64(*(*int321)(unsafe.Pointer(isec)))
	} else {
		*(*float64)(unsafe.Pointer(dsecfr)) = float64(*(*int321)(unsafe.Pointer(isec))) // is rounded, no fractional seconds
	}
}

/* end split_deg_nakshtra */

// C documentation
//
//	/************************************************************
//	 * splitting decimal degrees into (zod.sign,) deg, min, sec. *
//	 * input:
//	 * ddeg 	decimal degrees, ecliptic longitude
//	 * roundflag    by default there is no rounding. if rounding is
//	 *              required, the following bits can be set:
//	# define SE_SPLIT_DEG_ROUND_SEC    1
//	# define SE_SPLIT_DEG_ROUND_MIN    2
//	# define SE_SPLIT_DEG_ROUND_DEG    4
//	# define SE_SPLIT_DEG_ZODIACAL     8   * split into zodiac signs
//	# define SE_SPLIT_DEG_NAKSHATRA 1024   * split into nakshatras *
//	# define SE_SPLIT_DEG_KEEP_SIGN   16   * don't round to next zodiac sign,
//	                                       * e.g. 29.9999998 will be rounded
//					       * to 29°59'59" (or 29°59' or 29°) *
//					       * or next nakshatra:
//	                                       * e.g. 13.3333332 will be rounded
//					       * to 13°19'59" (or 13°19' or 13°) *
//	# define SE_SPLIT_DEG_KEEP_DEG    32   * don't round to next degree
//	                                       * e.g. 10.9999999 will be rounded
//					       * to 10d59'59" (or 10d59' or 10d) *
//	 * output:
//	 *  ideg 	degrees,
//	 *  imin 	minutes,
//	 *  isec 	seconds,
//	 *  dsecfr	fraction of seconds
//	 *  isgn	zodiac sign number;
//	 *              or +/- sign
//	 *
//	 *********************************************************/
func Xswe_split_deg(tls *libc.TLS, ddeg float64, roundflag int321, ideg uintptr, imin uintptr, isec uintptr, dsecfr uintptr, isgn uintptr) {
	var dadd float64
	_ = dadd
	dadd = libc.Float64FromInt32(0)
	*(*int321)(unsafe.Pointer(isgn)) = int32(1)
	if ddeg < libc.Float64FromInt32(0) {
		*(*int321)(unsafe.Pointer(isgn)) = -int32(1)
		ddeg = -ddeg
	} else {
		if roundflag&int32(SE_SPLIT_DEG_NAKSHATRA) != 0 {
			split_deg_nakshatra(tls, ddeg, roundflag, ideg, imin, isec, dsecfr, isgn)
			return
		}
	}
	if roundflag&int32(SE_SPLIT_DEG_ROUND_DEG) != 0 {
		dadd = float64(0.5)
	} else {
		if roundflag&int32(SE_SPLIT_DEG_ROUND_MIN) != 0 {
			dadd = libc.Float64FromFloat64(0.5) / libc.Float64FromFloat64(60)
		} else {
			if roundflag&int32(SE_SPLIT_DEG_ROUND_SEC) != 0 {
				dadd = libc.Float64FromFloat64(0.5) / libc.Float64FromFloat64(3600)
			}
		}
	}
	if roundflag&int32(SE_SPLIT_DEG_KEEP_DEG) != 0 {
		if int32(ddeg+dadd)-int32(ddeg) > 0 {
			dadd = libc.Float64FromInt32(0)
		}
	} else {
		if roundflag&int32(SE_SPLIT_DEG_KEEP_SIGN) != 0 {
			if libc.Xfmod(tls, ddeg, libc.Float64FromInt32(30))+dadd >= libc.Float64FromInt32(30) {
				dadd = libc.Float64FromInt32(0)
			}
		}
	}
	ddeg += dadd
	if roundflag&int32(SE_SPLIT_DEG_ZODIACAL) != 0 {
		*(*int321)(unsafe.Pointer(isgn)) = int32(ddeg / libc.Float64FromInt32(30))
		if *(*int321)(unsafe.Pointer(isgn)) == int32(12) { // 360° = 0°
			*(*int321)(unsafe.Pointer(isgn)) = 0
		}
		ddeg = libc.Xfmod(tls, ddeg, libc.Float64FromInt32(30))
	}
	*(*int321)(unsafe.Pointer(ideg)) = int32(ddeg)
	ddeg -= float64(*(*int321)(unsafe.Pointer(ideg)))
	*(*int321)(unsafe.Pointer(imin)) = int32(float64(ddeg * libc.Float64FromInt32(60)))
	ddeg -= float64(*(*int321)(unsafe.Pointer(imin))) / float64(60)
	*(*int321)(unsafe.Pointer(isec)) = int32(float64(ddeg * libc.Float64FromInt32(3600)))
	if !(roundflag&(libc.Int32FromInt32(SE_SPLIT_DEG_ROUND_DEG)|libc.Int32FromInt32(SE_SPLIT_DEG_ROUND_MIN)|libc.Int32FromInt32(SE_SPLIT_DEG_ROUND_SEC)) != 0) {
		*(*float64)(unsafe.Pointer(dsecfr)) = float64(ddeg*libc.Float64FromInt32(3600)) - float64(*(*int321)(unsafe.Pointer(isec)))
	} else {
		*(*float64)(unsafe.Pointer(dsecfr)) = float64(*(*int321)(unsafe.Pointer(isec))) // is rounded, no fractional seconds
	}
}

/* end split_deg */

func Xswi_kepler(tls *libc.TLS, E float64, M float64, ecce float64) (r float64) {
	var E0, dE, x float64
	_, _, _ = E0, dE, x
	dE = libc.Float64FromInt32(1)
	/* simple formula for small eccentricities */
	if ecce < float64(0.4) {
		for dE > float64(1e-12) {
			E0 = E
			E = M + float64(ecce*libc.Xsin(tls, E0))
			dE = libc.Xfabs(tls, E-E0)
		}
		/* complicated formula for high eccentricities */
	} else {
		for dE > float64(1e-12) {
			E0 = E
			/*
			 * Alois 21-jul-2000: workaround an optimizer problem in gcc
			 * swi_mod2PI sees very small negative argument e-322 and returns +2PI;
			 * we avoid swi_mod2PI for small x.
			 */
			x = (M + float64(ecce*libc.Xsin(tls, E0)) - E0) / (libc.Float64FromInt32(1) - float64(ecce*libc.Xcos(tls, E0)))
			dE = libc.Xfabs(tls, x)
			if dE < float64(0.01) {
				E = E0 + x
			} else {
				E = Xswi_mod2PI(tls, E0+x)
				dE = libc.Xfabs(tls, E-E0)
			}
		}
	}
	return E
}

func Xswi_FK4_FK5(tls *libc.TLS, xp uintptr, tjd float64) {
	var correct_speed AS_BOOL
	_ = correct_speed
	correct_speed = int32(TRUE)
	if *(*float64)(unsafe.Pointer(xp)) == libc.Float64FromInt32(0) && *(*float64)(unsafe.Pointer(xp + 1*8)) == libc.Float64FromInt32(0) && *(*float64)(unsafe.Pointer(xp + 2*8)) == libc.Float64FromInt32(0) {
		return
	}
	/* with zero speed, we assume that it should be really zero */
	if *(*float64)(unsafe.Pointer(xp + 3*8)) == libc.Float64FromInt32(0) {
		correct_speed = FALSE
	}
	Xswi_cartpol_sp(tls, xp, xp)
	/* according to Expl.Suppl., p. 167f. */
	*(*float64)(unsafe.Pointer(xp)) += float64(float64((float64(0.035)+float64(float64(0.085)*(tjd-float64(2.43328242345905e+06)))/float64(36524.2198782))/libc.Float64FromInt32(3600)*libc.Float64FromInt32(15)) * (libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180)))
	if correct_speed != 0 {
		*(*float64)(unsafe.Pointer(xp + 3*8)) += float64(float64(libc.Float64FromFloat64(0.085)/libc.Float64FromFloat64(36524.2198782)/libc.Float64FromInt32(3600)*libc.Float64FromInt32(15)) * (libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180)))
	}
	Xswi_polcart_sp(tls, xp, xp)
}

func Xswi_FK5_FK4(tls *libc.TLS, xp uintptr, tjd float64) {
	if *(*float64)(unsafe.Pointer(xp)) == libc.Float64FromInt32(0) && *(*float64)(unsafe.Pointer(xp + 1*8)) == libc.Float64FromInt32(0) && *(*float64)(unsafe.Pointer(xp + 2*8)) == libc.Float64FromInt32(0) {
		return
	}
	Xswi_cartpol_sp(tls, xp, xp)
	/* according to Expl.Suppl., p. 167f. */
	*(*float64)(unsafe.Pointer(xp)) -= float64(float64((float64(0.035)+float64(float64(0.085)*(tjd-float64(2.43328242345905e+06)))/float64(36524.2198782))/libc.Float64FromInt32(3600)*libc.Float64FromInt32(15)) * (libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180)))
	*(*float64)(unsafe.Pointer(xp + 3*8)) -= float64(float64(libc.Float64FromFloat64(0.085)/libc.Float64FromFloat64(36524.2198782)/libc.Float64FromInt32(3600)*libc.Float64FromInt32(15)) * (libc.Float64FromFloat64(3.141592653589793) / libc.Float64FromFloat64(180)))
	Xswi_polcart_sp(tls, xp, xp)
}

