			for tjdnoon-tjd0 < float64(0) { /*printf("g");*/
				tjdnoon += libc.Float64FromInt32(1)
			}
			for tjdnoon-tjd0 > float64(1) { /*printf("h");*/
				tjdnoon -= libc.Float64FromInt32(1)
			}
