func get_synodic_period(tls *libc.TLS, Planet int32) (r float64) {
	/* synodic periods from:
	 * Kelley/Milone/Aveni, "Exploring ancient Skies", p. 43. */
	switch Planet {
	case int32(SE_MOON):
		return float64(29.530588853)
	case int32(SE_MERCURY):
		return float64(115.8775)
	case int32(SE_VENUS):
		return float64(583.9214)
	case int32(SE_MARS):
		return float64(779.9361)
	case int32(SE_JUPITER):
		return float64(398.884)
	case int32(SE_SATURN):
		return float64(378.0919)
	case int32(SE_URANUS):
		return float64(369.656)
	case int32(SE_NEPTUNE):
		return float64(367.4867)
	case int32(SE_PLUTO):
		return float64(366.7207)
	}
	return libc.Float64FromInt32(366) /* for stars and default for far away planets */
}

