	is_rise_or_set = 0
	direct_day = libc.Float64FromInt32(0)
	direct_time = libc.Float64FromInt32(0)
	ipl = DeterObject(tls, ObjectName)
	/*
	 * find the day and minute on which the object becomes visible
	 */
	switch TypeEvent {
	/* morning first */
	case int32(1):
		is_rise_or_set = int32(SE_CALC_RISE)
		direct_day = libc.Float64FromInt32(1)
		direct_time = float64(-libc.Int32FromInt32(1))
		break
		/* evening last */
		fallthrough
	case int32(2):
		is_rise_or_set = int32(SE_CALC_SET)
		direct_day = float64(-libc.Int32FromInt32(1))
		direct_time = libc.Float64FromInt32(1)
		break
		/* evening first */
		fallthrough
	case int32(3):
		is_rise_or_set = int32(SE_CALC_SET)
		direct_day = libc.Float64FromInt32(1)
		direct_time = libc.Float64FromInt32(1)
		break
		/* morning last */
		fallthrough
	case int32(4):
		is_rise_or_set = int32(SE_CALC_RISE)
		direct_day = float64(-libc.Int32FromInt32(1))
		direct_time = float64(-libc.Int32FromInt32(1))
		break
	}
